struct pm_scan_arg {
    __u64 start, length;    // Input: Range to scan
    __u64 vec_size, flags;  // Input: Flags (PAGEMAP_SCAN_VALID, etc.)
    void *vec;              // Output: Array of results
};

// PAGEMAP_SCAN is the ioctl request code
int pagemap_fd; // File descriptor for /proc/pid/pagemap
struct pm_scan_arg arg = {
    .start = 0, .length = 1UL << 30,
    .flags = PAGEMAP_SCAN_CLEAR,
    .vec_size = 1024, .vec = result_buffer,
};

// Returns number of pages processed on success
long pages_scanned = ioctl(pagemap_fd, PAGEMAP_SCAN, &arg);

// Error case: pages_scanned < 0 (errno set, e.g., EINVAL)
if (pages_scanned < 0) { /* handle error */ }
